import fs from 'node:fs';
import vm from 'node:vm';

const context={window:{}};
vm.createContext(context);
vm.runInContext(fs.readFileSync(new URL('../informatique-bank.js',import.meta.url),'utf8'),context);

const chapters=context.window.QINFO_BANK.chapters;
const sourceBase=context.window.QINFO_BANK.questions;
const extras=[];
const add=(c,t,prompt,correct,wrong,why,source)=>{
  if(!Array.isArray(wrong)||wrong.length!==3)throw new Error(`Trois distracteurs requis : ${prompt}`);
  extras.push({c,t,prompt,correct,wrong,why,source});
};

const promptFixes=new Map([
  ['Que désigne le cloud dans le cours ?','Que désigne le cloud ?'],
  ['Dans le cours, la « mort numérique » concerne principalement :','Que concerne principalement la « mort numérique » ?'],
  ['Comment le cours définit-il la blockchain ?','Quelle définition correspond à la blockchain ?'],
  ['Quelle définition correspond le mieux à la cybercriminalité dans le cours ?','Quelle définition correspond le mieux à la cybercriminalité ?'],
  ['Quel effet environnemental du numérique est explicitement cité dans le cours ?','Lequel de ces phénomènes constitue un impact environnemental du numérique ?'],
  ['Dans le cadre de l’administration, quel objectif est associé à l’intelligence artificielle dans le cours ?','Quel objectif peut être associé à l’intelligence artificielle dans l’administration ?'],
  ['Lorsque le Data Act concerne des données personnelles et qu’une contradiction apparaît avec le RGPD, quel texte prévaut selon le cours ?','Lorsque le Data Act concerne des données personnelles et qu’une contradiction apparaît avec le RGPD, quel texte prévaut ?']
]);

const explanationFixes=new Map([
  ['Le cours recommande de vérifier la provenance des informations et de les recouper avec d’autres sources.','La fiabilité d’une information se contrôle en vérifiant sa provenance et en la recoupant avec plusieurs sources.'],
  ['Le cours présente le dark web comme une partie particulière du deep web, accessible au moyen de technologies spécifiques.','Le dark web est une partie particulière du deep web, accessible au moyen de réseaux ou logiciels spécifiques.'],
  ['Le cours souligne l’énergie consommée, les ressources nécessaires aux équipements et les déchets électroniques.','L’impact environnemental comprend l’énergie consommée, les ressources nécessaires à la fabrication et les déchets électroniques.'],
  ['Le cours évoque l’accompagnement de projets d’IA et leur usage au service de l’action publique.','L’intelligence artificielle peut accompagner certains projets et améliorer des services ou processus publics.'],
  ['Le cours présente des règles de protection des mineurs et d’encadrement de certains contenus audiovisuels.','Le cadre européen protège notamment les mineurs et encadre certains contenus audiovisuels.'],
  ['Le cours précise que le RGPD prévaut lorsqu’il s’agit de données personnelles.','Le RGPD prévaut en cas de contradiction dès lors que des données personnelles sont concernées.'],
  ['Le cours décrit des règles destinées à faciliter le changement de fournisseur et l’interopérabilité.','La portabilité et l’interopérabilité réduisent les obstacles au changement de fournisseur cloud.'],
  ['Le cours rappelle qu’un traitement doit reposer sur une base légale.','Tout traitement de données personnelles doit reposer sur une base juridique appropriée.'],
  ['Le cours précise que les obligations concernent toute structure privée ou publique traitant des données personnelles.','Les obligations s’appliquent aux structures privées comme publiques lorsqu’elles traitent des données personnelles.'],
  ['Le cours présente notamment une mission d’information et de protection des droits.','La CNIL informe les personnes et les aide à exercer leurs droits.'],
  ['Le cours présente la CNIL comme chargée d’accompagner l’innovation tout en protégeant les libertés.','La CNIL accompagne l’innovation numérique tout en veillant à la protection des droits et libertés.'],
  ['Le cours cite notamment les cryptomonnaies comme Bitcoin et Ethereum.','Les cryptomonnaies comme Bitcoin et Ethereum constituent des usages emblématiques de la blockchain.'],
  ['Le cours distingue la création de documents textuels et multimédias.','Un traitement de texte est adapté à la rédaction et à la mise en forme d’un document principalement écrit.'],
  ['Le cours cite AZERTY pour les claviers francophones et QWERTY pour les claviers anglophones.','AZERTY est la disposition courante des claviers francophones, tandis que QWERTY domine dans les pays anglophones.'],
  ['Le cours distingue les infractions visant les systèmes et celles facilitées par les technologies numériques.','La cybercriminalité regroupe les infractions qui ciblent les systèmes ou qui utilisent les technologies numériques comme moyen ou support.'],
  ['Le cours rattache le cyberharcèlement à des comportements numériques répétés portant atteinte à une personne.','Le cyberharcèlement se caractérise par la répétition d’agissements numériques portant atteinte à une personne.'],
  ['Le cours associe le chiffrement à des mécanismes tels que les signatures numériques pour contrôler l’intégrité.','Des mécanismes cryptographiques, comme la signature numérique, permettent de détecter une modification des données.'],
  ['Le cours distingue Internet, réseau de réseaux, et le Web, service reposant sur Internet.','Internet est un réseau de réseaux ; le Web est l’un des services qui utilisent cette infrastructure.'],
  ['Le cours mentionne la fibre optique comme support essentiel du réseau national et international.','La fibre optique transporte de grandes quantités de données et constitue un support majeur des réseaux fixes.'],
  ['Le cours cite notamment les droits d’information, d’accès, de rectification, d’opposition et d’effacement.','Le RGPD reconnaît notamment les droits d’information, d’accès, de rectification, d’opposition et d’effacement.'],
  ['Le cours prévoit des pouvoirs de mise en demeure et de sanction en cas de manquement.','La CNIL peut mettre en demeure un organisme et prononcer des sanctions selon la nature et la gravité du manquement.']
]);

const moveToA5=new Set([
  'Que désigne l’identité numérique ?',
  'À quoi correspond principalement le droit au déréférencement ?',
  'Dans le cours, la « mort numérique » concerne principalement :'
]);
const base=sourceBase.map(item=>{
  const options=[...item.o];
  const correct=options[item.a];
  const wrong=options.filter((_,i)=>i!==item.a);
  return {
    c:moveToA5.has(item.q)?'A5':item.c,
    t:item.t,
    prompt:promptFixes.get(item.q)||item.q.replace(/\s+d['’]après le cours/gi,'').replace(/\s+selon le cours/gi,'').replace(/\s+dans le cours/gi,''),
    correct,
    wrong,
    why:explanationFixes.get(item.e)||item.e.replace(/Le cours (présente|rappelle|recommande|évoque|précise|décrit|souligne)/g,(_,v)=>({présente:'Cette notion présente',rappelle:'Il faut retenir',recommande:'La bonne pratique consiste',évoque:'Cette notion comprend',précise:'La règle précise',décrit:'Ce mécanisme décrit',souligne:'Cet impact comprend'}[v])),
    source:item.s
  };
});

// A1 — Informations et données : 26 questions nouvelles (38 avec la base).
add('A1','Données','Une administration transforme une date de naissance en valeur exploitable par son logiciel. Que devient cette information ?','Une donnée numérique',['Un pare-feu','Un protocole réseau','Une licence libre'],'Une donnée est la représentation d’une information sous une forme qu’un système numérique peut enregistrer et traiter.','Culture numérique 1 · p. 199');
add('A1','Données','Laquelle de ces listes contient uniquement des formes possibles de données numériques ?','Texte, nombres, images et sons',['Mémoire vive, processeur, clavier et écran','Pare-feu, antivirus, mot de passe et chiffrement','Cloud, fibre, Wi-Fi et navigateur'],'Une donnée peut prendre une forme textuelle, numérique, visuelle ou sonore ; les autres séries mélangent matériels, protections et réseaux.','Culture numérique 1 · p. 199');
add('A1','Données','Quelle unité élémentaire d’information ne peut prendre que les valeurs 0 ou 1 ?','Le bit',['L’octet','Le pixel','Le fichier'],'Le bit est l’unité binaire élémentaire. Un octet regroupe plusieurs bits, tandis qu’un pixel ou un fichier constitue un objet d’un autre niveau.','Culture numérique 1 · p. 199');
add('A1','Mémoire','Un document non enregistré disparaît après une coupure de courant. Quelle mémoire contenait principalement les données en cours d’utilisation ?','La mémoire vive (RAM)',['Le disque dur','Le SSD','La mémoire de masse externe'],'La RAM est volatile : elle conserve temporairement les données nécessaires au travail en cours et perd son contenu à l’arrêt.','Culture numérique 1 · p. 199');
add('A1','Mémoire','Quel composant fournit au processeur un espace de stockage extrêmement rapide pour ses opérations immédiates ?','Les registres du processeur',['Le disque dur externe','Le data center','La mémoire de masse'],'Les registres sont intégrés au processeur et conservent de très petites quantités de données utilisées immédiatement.','Culture numérique 1 · p. 199');
add('A1','Mémoire','Pourquoi la mémoire cache accélère-t-elle le traitement informatique ?','Elle conserve à proximité du processeur des données fréquemment utilisées',['Elle remplace définitivement tous les supports de stockage','Elle chiffre automatiquement chaque fichier','Elle augmente la vitesse de la connexion internet'],'La mémoire cache réduit certains temps d’accès en gardant disponibles des informations souvent sollicitées par le processeur.','Culture numérique 1 · p. 199');
add('A1','Mémoire','Un ordinateur utilise une partie de son disque pour simuler de la mémoire vive supplémentaire. Quel mécanisme est employé ?','La mémoire virtuelle',['Le data mining','Le chiffrement asymétrique','L’indexation du Web'],'La mémoire virtuelle utilise un support de stockage pour simuler une extension de la RAM, généralement avec des performances inférieures.','Culture numérique 1 · p. 199');
add('A1','Mémoire','Quelle association distingue correctement RAM et mémoire de masse ?','RAM — travail temporaire ; mémoire de masse — conservation durable',['RAM — conservation durable ; mémoire de masse — calcul du processeur','RAM — filtrage du réseau ; mémoire de masse — chiffrement','RAM — traduction des noms de domaine ; mémoire de masse — indexation du Web'],'La RAM sert aux opérations en cours et reste volatile ; la mémoire de masse conserve les fichiers après l’arrêt de la machine.','Culture numérique 1 · p. 199');
add('A1','Recherche','Pour rechercher une décision administrative précise, quelle requête est la plus efficace ?','Quelques mots-clés distinctifs liés à la décision recherchée',['Une phrase très longue racontant tout le contexte personnel','Un seul mot extrêmement général','Le nom du navigateur utilisé'],'Une recherche gagne en précision lorsque la question est résumée par des mots-clés pertinents et suffisamment distinctifs.','Culture numérique 1 · p. 200-202');
add('A1','Fiabilité','Pourquoi le premier résultat affiché par un moteur de recherche ne doit-il pas être tenu automatiquement pour vrai ?','Le classement mesure la pertinence estimée, pas la véracité garantie',['Les moteurs n’indexent jamais de pages fiables','Le premier résultat est toujours une publicité','Les résultats récents sont nécessairement faux'],'Un algorithme classe des résultats selon divers critères ; cette position ne dispense jamais de vérifier l’auteur, la source et les preuves.','Culture numérique 1 · p. 200-202');
add('A1','Fiabilité','Une information spectaculaire n’apparaît que sur un site anonyme. Quel contrôle faut-il effectuer en priorité ?','Identifier la source puis rechercher des confirmations indépendantes',['La partager pour demander ensuite si elle est vraie','La croire parce qu’elle est récente','Se fier uniquement au nombre de commentaires'],'La provenance et le recoupement avec plusieurs sources fiables sont essentiels pour limiter la désinformation.','Culture numérique 1 · p. 200-202');
add('A1','Moteur de recherche','Que fait principalement un moteur de recherche avant de pouvoir proposer des pages en réponse à une requête ?','Il explore et indexe des pages du Web',['Il transforme toutes les pages en données publiques','Il vérifie juridiquement chaque phrase publiée','Il héberge obligatoirement chaque site affiché'],'Le moteur construit un index des pages repérées, puis interroge cet index pour classer les résultats correspondant à la requête.','Culture numérique 1 · p. 200-202');
add('A1','Recherche avancée','Une recherche renvoie trop de résultats sans rapport avec le sujet. Quelle action est la plus pertinente ?','Ajouter des critères ou filtres de recherche précis',['Changer la luminosité de l’écran','Effacer la mémoire vive','Désactiver le pare-feu'],'La recherche avancée sert à restreindre les résultats par des critères adaptés plutôt qu’à modifier le matériel ou la sécurité.','Culture numérique 1 · p. 200-202');
add('A1','Cloud','Une agente ouvre depuis plusieurs appareils des fichiers conservés sur des serveurs distants. Quel service utilise-t-elle ?','Un service cloud',['Une mémoire cache','Un pare-feu local','Un moteur de rendu graphique'],'Le cloud met à disposition, par le réseau, des ressources informatiques et des données hébergées à distance.','Culture numérique 1 · p. 205-206');
add('A1','Cloud','Quelle affirmation relie correctement cloud et data center ?','Le cloud fournit des services distants qui reposent notamment sur des serveurs situés dans des data centers',['Le data center est une application installée dans la RAM','Le cloud est un bâtiment qui ne contient aucun serveur','Les deux termes désignent uniquement une connexion Wi-Fi'],'Le cloud décrit un mode d’accès à des ressources ; le data center est l’infrastructure physique regroupant des serveurs.','Culture numérique 1 · p. 205-206');
add('A1','Data mining','Une administration analyse des millions de dossiers pour repérer des régularités invisibles à l’œil nu. Quelle technique mobilise-t-elle ?','Le data mining',['Le droit au déréférencement','Le webmail','La charte graphique'],'Le data mining explore de grands volumes de données afin d’en extraire des tendances, corrélations ou connaissances utiles.','Culture numérique 1 · p. 205-206');
add('A1','Données massives','Quelle opération relève du data mining plutôt que du simple stockage ?','Détecter des relations récurrentes dans un vaste ensemble de données',['Copier des fichiers sur un disque externe','Augmenter la capacité d’une mémoire vive','Classer manuellement quatre documents dans un dossier'],'Le data mining consiste à analyser les données pour produire de l’information, et non seulement à les conserver.','Culture numérique 1 · p. 205-206');
add('A1','Intelligence artificielle','Une IA donne une réponse très assurée mais invente une référence. Quel réflexe faut-il adopter ?','Vérifier la référence dans des sources fiables avant de l’utiliser',['La conserver parce que le ton est convaincant','La publier immédiatement en mentionnant seulement l’IA','Considérer que toute réponse automatisée est validée'],'Une IA peut produire une information plausible mais fausse. L’assurance de la formulation n’est pas une preuve.','Culture numérique 1 · p. 200');
add('A1','Intelligence artificielle','Pourquoi des résultats produits par une IA peuvent-ils reproduire des discriminations ?','Les données ou choix de conception peuvent contenir des biais',['Toute IA refuse nécessairement les données','Une IA fonctionne sans modèle ni entraînement','Le chiffrement transforme automatiquement les réponses en préjugés'],'Les biais présents dans les données, les objectifs ou la conception peuvent se retrouver dans les résultats.','Culture numérique 1 · p. 200');
add('A1','Intelligence artificielle','Avant de transmettre à une IA publique un dossier contenant des informations sensibles, quelle question est prioritaire ?','Savoir comment les données seront utilisées, protégées et conservées',['Choisir la réponse la plus longue','Vérifier la couleur de l’interface','Augmenter le volume sonore de l’appareil'],'L’usage d’une IA peut soulever un enjeu de protection des données ; il faut connaître les conditions de traitement avant toute transmission.','Culture numérique 1 · p. 200');
add('A1','Intelligence artificielle','Quel ensemble rassemble uniquement des enjeux liés à l’usage d’une IA ?','Biais, protection des données, propriété intellectuelle et responsabilité',['Résolution de l’écran, taille du clavier, batterie et volume','Adresse postale, timbre, enveloppe et affranchissement','Fibre, charrue, imprimerie et boussole'],'L’IA soulève notamment des questions de biais, de données personnelles, de droits sur les contenus et d’attribution de la responsabilité.','Culture numérique 1 · p. 200');
add('A1','Web','Un espace personnel accessible après authentification n’apparaît pas dans les résultats d’un moteur de recherche. À quelle partie du Web appartient-il généralement ?','Au deep web',['Au clear web indexé','À un réseau local hors Internet par définition','À la mémoire cache du navigateur'],'Le deep web comprend les pages non indexées, par exemple certains espaces privés ou contenus générés pour un utilisateur.','Culture numérique 2 · p. 212');
add('A1','Web','Quelle caractéristique définit le clear web, ou Web surfacique ?','Ses pages sont indexées par les moteurs de recherche',['Il exige toujours un logiciel d’anonymisation','Il ne contient que des données administratives','Il est intégralement protégé par mot de passe'],'Le clear web correspond à la partie du Web que les moteurs peuvent indexer et proposer dans leurs résultats.','Culture numérique 2 · p. 212');
add('A1','Web','Quelle relation entre deep web et dark web est correcte ?','Le dark web est une partie du deep web accessible par des réseaux ou outils spécifiques',['Le deep web est une petite partie du dark web','Les deux expressions désignent exactement toutes les pages indexées','Le dark web correspond uniquement aux fichiers stockés hors ligne'],'Le deep web rassemble les pages non indexées ; le dark web en constitue une partie reposant sur des réseaux spécifiques.','Culture numérique 2 · p. 212');
add('A1','Web','Une personne affirme que tout contenu du dark web est illégal. Quelle correction est juste ?','L’accès ou le contenu n’est pas automatiquement illégal, même si des activités illicites y existent',['Tout contenu y est validé par l’État','Le dark web ne peut héberger aucune activité criminelle','Le dark web désigne seulement les courriels professionnels'],'Le dark web peut accueillir des usages licites comme illicites ; il ne faut pas confondre technologie d’accès et légalité du contenu.','Culture numérique 2 · p. 212');
add('A1','Synthèse','Quelle chaîne décrit correctement trois niveaux différents ?','Data center — infrastructure physique ; cloud — service distant ; data mining — analyse de données',['Data center — moteur de recherche ; cloud — mémoire vive ; data mining — pare-feu','Data center — licence ; cloud — droit d’auteur ; data mining — chiffrement','Data center — nom de domaine ; cloud — adresse IP ; data mining — navigateur'],'Le data center héberge les équipements, le cloud rend des ressources accessibles à distance et le data mining extrait des connaissances des données.','Culture numérique 1 · p. 205-206');
add('A1','Veille informationnelle','Quelle activité correspond à une veille informationnelle ?','Surveiller régulièrement des sources choisies pour repérer les nouveautés d’un domaine',['Effectuer une recherche unique puis ne plus actualiser ses informations','Sauvegarder tous ses fichiers sans les consulter','Changer de moteur de recherche chaque jour sans objectif'],'La veille est une surveillance organisée et continue, alors qu’une recherche ponctuelle répond à un besoin immédiat.','Culture numérique 1 · p. 200-202');
add('A1','Fiabilité','Deux articles donnent des chiffres différents. Quel élément aide le mieux à comprendre l’écart ?','Comparer leurs dates, leurs sources et leurs méthodes',['Choisir celui dont le titre est le plus affirmatif','Retenir automatiquement le chiffre le plus élevé','Compter le nombre de couleurs présentes sur chaque page'],'La date, l’origine des données et la méthode employée permettent d’évaluer et d’expliquer des résultats divergents.','Culture numérique 1 · p. 200-202');
add('A1','Données','Quel exemple correspond à des données structurées ?','Un tableau où chaque ligne est un dossier et chaque colonne un champ défini',['Une photographie sans métadonnée ni classement','Un enregistrement sonore continu','Une vidéo non découpée'],'Des données structurées suivent une organisation explicite qui facilite leur tri, leur recherche et leur traitement automatique.','Culture numérique 1 · p. 199');

