for(const item of [...base,...extras]){
  const fix=corrections.get(item.prompt);
  if(fix)Object.assign(item,fix);
}

const targets={A1:38,A2:28,A3:20,A4:38,A5:32,B1:32,B2:34,B3:34,C1:34,C2:30};

function normalize(s){return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}

function finalize(){
  const raw=[...base,...extras];
  const order=chapters.map(ch=>ch.id);
  raw.sort((a,b)=>order.indexOf(a.c)-order.indexOf(b.c));
  const chapterTitles=Object.fromEntries(chapters.map(ch=>[ch.id,ch.title]));
  const bank=raw.map((item,index)=>{
    const number=index+1;
    const canonical=[item.correct,...item.wrong];
    const shift=(number-1)%4;
    const o=canonical.slice(shift).concat(canonical.slice(0,shift));
    const ans=o.indexOf(item.correct);
    return {
      number,id:`CN-${String(number).padStart(4,'0')}`,
      chapterId:item.c,chapter:chapterTitles[item.c],topic:item.t,
      prompt:item.prompt,o,ans,why:item.why,source:item.source,
      c:item.c,t:item.t,q:item.prompt,a:ans,e:item.why,s:item.source
    };
  });
  const counts=Object.fromEntries(order.map(c=>[c,bank.filter(q=>q.chapterId===c).length]));
  for(const [c,target] of Object.entries(targets))if(counts[c]!==target)throw new Error(`${c}: ${counts[c]} questions au lieu de ${target}`);
  if(bank.length!==320)throw new Error(`Total invalide : ${bank.length}`);
  const prompts=new Set();
  for(const q of bank){
    if(q.o.length!==4||new Set(q.o.map(normalize)).size!==4)throw new Error(`Options invalides : ${q.id}`);
    if(q.ans<0||q.ans>3)throw new Error(`Réponse invalide : ${q.id}`);
    const key=normalize(q.prompt);
    if(prompts.has(key))throw new Error(`Question dupliquée : ${q.prompt}`);
    prompts.add(key);
    if(/selon le cours|d.apres le cours|dans le cours/i.test(normalize(q.prompt)))throw new Error(`Référence au cours : ${q.id}`);
  }
  const out=`window.QCULTURENUMERIQUE_REVIEW=${JSON.stringify(bank,null,2)};\n`;
  fs.writeFileSync(new URL('../culture-numerique-320-bank.js',import.meta.url),out);
  fs.writeFileSync(new URL('../drafts/audit-culture-numerique-320.json',import.meta.url),JSON.stringify({total:bank.length,counts,answerPositions:[0,1,2,3].map(i=>bank.filter(q=>q.ans===i).length)},null,2)+'\n');
  console.log(JSON.stringify({total:bank.length,counts,answerPositions:[0,1,2,3].map(i=>bank.filter(q=>q.ans===i).length)},null,2));
}

